    # Seed outline cells from adjacent colored regions, then propagate each
    # seed's color along its connected outline.
    dist = [[-1] * w for _ in range(h)]
    color = [[None] * w for _ in range(h)]
    q = deque()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != wall:
                continue
            around = Counter()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                y, x = r + dr, c + dc
                if 0 <= y < h and 0 <= x < w:
                    v = grid[y][x]
                    if v not in (bg, wall):
                        around[v] += 1
            if around:
                best = around.most_common()
                if len(best) == 1 or best[0][1] > best[1][1]:
                    dist[r][c] = 0
                    color[r][c] = best[0][0]
                    q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            y, x = r + dr, c + dc
            if (0 <= y < h and 0 <= x < w and grid[y][x] == wall
                    and dist[y][x] == -1):
                dist[y][x] = dist[r][c] + 1
                color[y][x] = color[r][c]
                q.append((y, x))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
